# owner: platform
from typing import Iterable, List

from rosterkit.models import Student


def _require_email(student: Student) -> None:
    if not student.email:
        raise ValueError(f"no email for {student.display_name}")


def _contact_row(student: Student, width: int) -> str:
    name = f"{student.display_name:<{width}}"
    return f"{name}  {student.section:<8}  {student.email}"


# ---
def contact_sheet(students: Iterable[Student]) -> List[str]:
    ordered = sorted(students, key=lambda item: item.display_name)
    if not ordered:
        raise ValueError("no students to list")
    for person in ordered:
        _require_email(person)
    width = max(len(person.display_name) for person in ordered)
    return [_contact_row(person, width) for person in ordered]

