# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_sheet


def _student(last, first, email="x@example.org"):
    return Student("1", last, first, "A", email)


class ContactSheetTests(unittest.TestCase):
    # ---
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_sheet([_student("Zed", "Al"), _student("Lee", "Bo")])
        self.assertEqual(rows[0], "Lee, Bo  A         x@example.org")
        self.assertEqual(rows[1], "Zed, Al  A         x@example.org")

    # ---
    def test_missing_email_names_the_student(self):
        with self.assertRaisesRegex(ValueError, "Lee, Bo"):
            contact_sheet([_student("Lee", "Bo", None)])

    # ---
    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_sheet([])
